  const fmt=v=>Number(v||0).toLocaleString('fr-FR'),date=v=>v?new Date(v).toLocaleDateString('fr-FR'):'—',dateTime=v=>v?new Date(v).toLocaleString('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Jamais';
  const labels={draft:'Brouillon',configuration_submitted:'À relire',review_pending:'À relire',in_review:'En relecture',client_validation_required:'Validation client requise',ready_to_publish:'Prête à publier',scheduled:'Programmée',published:'Publiée',active:'En cours',completed:'Terminée',unpublished:'Dépubliée'},pages={'index.html':'Accueil','composer.html':'Questions','personnalisation.html':'Profils','parametrage.html':'Paramétrage','validation.html':'Validation','mes-campagnes.html':'Mes campagnes','campagne-detail.html':'Détail campagne','account.html':'Mon compte','packs.html':'Commander des passations'};
  const state={organizations:[],activity:[],administrators:[],currentUserId:null,orgFilter:'all',clientFolderFilter:'all',clientFolders:[],clientUsers:new Map(),adminUsers:new Map(),catalogThemes:[],catalogLoaded:false,libraryThemeId:null,libraryExpandedChapters:new Set()};
  const orgDialog=$('#org-dialog'),userDialog=$('#user-dialog'),adminUserDialog=$('#admin-user-dialog'),contactsRoot=$('#org-contacts');
  const orgUsers=o=>Array.isArray(o.users)?o.users:[],orgProjects=o=>Array.isArray(o.projects)?o.projects:[],orgSectors=o=>Array.isArray(o.sectors)&&o.sectors.length?o.sectors:(o.sector?[o.sector]:[]),orgThemes=o=>{const counts=new Map();orgProjects(o).forEach(p=>{const t=String(p.theme_title||'').trim();if(t)counts.set(t,(counts.get(t)||0)+1);});return[...counts.entries()].sort((a,b)=>a[0].localeCompare(b[0]));},remaining=o=>o.pack_unlimited?null:Math.max(0,Number(o.passations_quota||0)-Number(o.passations_used||0));
